  "Adds bodycams to the register and updates the ones already there, matched by serial number. Who has a bodycam right now never changes by import; that happens only when it is booked out or handed back.": "Kwengeta emakhamera emtimba kurejista futsi kuvuselela lasevele akhona, ngekucatsanisa inombolo ye-serial. Lophetse ikhamera yemtimba nyalo akashintji ngekungenisa; loko kwenteka kuphela nangabe ikhishwa nome ibuyiswa.",
  "Adds firearms to the register and updates the ones already there, matched by serial number. Who holds a firearm right now never changes by import; that happens only when it is booked out or handed back.": "Kwengeta tibhamu kurejista futsi kuvuselela letisevele tikhona, ngekucatsanisa inombolo ye-serial. Lophetse sibhamu nyalo akashintji ngekungenisa; loko kwenteka kuphela nangabe sikhishwa nome sibuyiswa.",
  "Adds people to the staff register and updates the ones already there, matched by badge number. Nobody gets access: each person is invited afterwards and activates their own account.": "Kwengeta bantfu kurejista yetisebenti futsi kuvuselela labasevele bakhona, ngekucatsanisa inombolo yebheji. Kute lotfola kufinyelela: umuntfu ngamunye uyamenywa ngemuva bese avula i-akhawunti yakhe.",
  "Adds vehicles to the register and updates the ones already there, matched by department and unit number. A vehicle’s status never changes by import: one off the road stays off the road until fleet control returns it.": "Kwengeta timoto kurejista futsi kuvuselela letisevele tikhona, ngekucatsanisa litiko nenombolo yeyunithi. Simo semoto asishintji ngekungenisa: lengekho emgwaceni ihlala ingekho kuze kulawulwa kwetimoto kuyibuyise.",
  "Adjustment": "Kulungiswa",
  "Admin": "Umphatsi",
