  "Each call sign is a row: pick the member for it.": "Luphawu ngalunye lwekubita lulayini: khetsa lilunga lalo.",
  "Each call sign is one duty slot: where it patrols, its hours, its break and the rank it needs. Duty Allocation books staff onto these.": "Luphawu ngalunye lwekubita sikhala sinye semsebenti: lapho lugadza khona, ema-awa alo, likhefu lalo nelizinga leludzingako. Kwabiwa Kwemsebenti kubhukha basebenti kuto.",
  "Each call sign with its area, hours and the rank it needs.": "Luphawu ngalunye lwekubita nendzawo yalo, ema-awa nelizinga leludzingako.",
  "Each day's reports, by where they stand.": "Imibiko yelilanga ngalinye, ngekwalapho ime khona.",
  "Each link or code works once and expires after {invitationTtlHours} hours. Sending again cancels the old one.": "Sixhumanisi nome ikhodi ngayinye isebenta kanye futsi iphelelwa sikhatsi ngemuva kwemahora langu-{invitationTtlHours}. Kutfumela futsi kukhansela lendzala.",
  "Each member’s record as the old system kept it: numbers, rank, station, section, weekend group, contacts, LEO record and screen access.": "Irekhodi yelilunga ngalinye njengobe sistimu lendzala beyiyigcine: tinombolo, lizinga, siteshi, sigaba, licembu leliphelasontfo, labachumana nabo, irekhodi ye-LEO nekungena esikrinini.",
  "Each patient and how bad they are": "Siguli ngasinye nekutsi sibi kangakanani",
  "Each person gets their own invitation, as their confirmed role, by the route shown: email where HR gave an address, SMS where there is only a cellphone{value}, otherwise a printed code. Each link or code works once and expires after its set time.": "Umuntfu ngamunye utfola simemo sakhe, njengendzima yakhe lecinisekisiwe, ngendlela lekhonjisiwe: i-imeyili lapho i-HR inikete likheli, i-SMS lapho kunaliselula kuphela{value}, nangabe kungenjalo ikhodi leshicilelwe. Sixhumanisi nome ikhodi ngayinye isebenta kanye futsi iphelelwa sikhatsi ngemuva kwesikhatsi sayo lesibekiwe.",
  "Each rule acts at most once per thing per threshold — a call that breaches its SLA raises one alert at each tier, not one every five minutes. Thresholds are stored per rule, so changing “escalate after 10 minutes” to 15 needs no deployment. Every change and every manual run is written to the audit trail with your name on it.": "Umtsetfo ngamunye wenta kanye kuphela entfweni ngayinye emkhawulweni ngamunye — lucingo lolwendlula i-SLA yalo luvusa secwayiso sinye ezingeni ngalinye, hhayi sinye njalo ngemizuzu lesihlanu. Imikhawulo igcinwa ngemtsetfo ngamunye, ngako kushintja \"khuphula ngemuva kwemizuzu le-10\" kuye ku-15 akudzingi kufakwa. Lonkhe lushintjo nako konkhe kuchutjwa ngesandla kubhalwa emkhondvweni wekuhlolwa neligama lakho.",
  "Each service's identity — crest, colours and naming — as it appears across the platform, the responder app and printed reports.": "Bunjalo belusito ngalunye — luphawu, imibala nemagama — njengoba kuvela kuphulathifomu yonkhe, ku-app yebaphendvuli nasemibikweni leshicilelwe.",
