  "Emulators and simulators cannot register for push. Alerts still arrive while the app is open.": "Ema-emulator nema-simulator awakhoni kubhalisela tatiso. Tecwayiso tisafika nangabe i-app ivuliwe.",
  "En Route": "Usendleleni",
  "En route": "Usendleleni",
  "Enabled": "Kuvuliwe",
  "Enabling a feature never grants a role anything the route matrix and row-level security would not — the two systems compose. Disabling one hides it everywhere and makes its server routes refuse, for this tenant only.": "Kuvula sici akuniki indzima lutfo i-matrix yetindlela nekuphepha kwelizinga lemugca lebekungeke kukuvumele — letinhlelo letimbili tisebenta ndzawonye. Kuvala sinye kusifihla yonkhe indzawo futsi kwenta tindlela taso telisevha tale, kulomcashi kuphela.",
