  "Ending a shift in the app is not switched on for this server yet. Hand your kit in at the counter and tell your supervisor.": "Kucedza shifti nge-app akukavulwa kulelisevha. Nikela timphahla takho ekhawunta bese utjela umphatsi wakho.",
