  "For a call that will never have a report: a hoax, a duplicate, or the caller cancelled.{value}": "Lucingo lolungasoze lube nembiko: emanga, lokuphindziwe, nome umshayi ukhanseliwe.{value}",
  "For a notice issued in error. It stays on the register, marked cancelled, with your reason. Refund any money first.": "Sativiso lesikhishwe ngephutsa. Sihlala erejistini, simakwe njengesikhanseliwe, nesizatfu sakho. Buyisela nome ngumuphi imali kucala.",
  "For a notice written in a notice book. Copy it exactly as written, with the printed notice number. Notices at the roadside are issued on the phone, where the infringer signs.": "Sativiso lesibhalwe encwadzini yetativiso. Sikopishe ngco njengoba sibhaliwe, nenombolo yesativiso lephrintiwe. Tativiso tasemgwaceni tikhishwa elucingweni, lapho lowephulako asayina khona.",
  "For example towards the taxi rank": "Sibonelo, ubheke erenki yematekisi",
  "For example: radio from a security guard": "Sibonelo: umsakato lovela kunogadi",
  "For example: the caller rang back with the right address": "Sibonelo: umshayi uphindze washaya nelikheli lelifanele",
  "For leave on a form the member handed in, sick leave, or an absence such as AWOL. It is approved as captured and their duty in those dates is marked.": "Kulikhefu kufomu lelilunga lelilinikile, likhefu lekugula, nobe kungabikhona njenge-AWOL. Lamukelwa njengobe lifakiwe futsi umsebenti wabo kulawo malanga uyaphawulwa.",
  "For the whole organisation. Office-hours rotations skip them, and they are not counted as leave days.": "Kwenhlangano yonkhe. Kushintjana kwemahora asehhovisi kuyatseya, futsi akubalwa njengemalanga ekuphumula.",
  "For their shift": "Ku-shift yabo",
