  "How often this rule is evaluated. The scheduler ticks every 5 minutes, so anything below that runs every tick.": "Kutsi lomtsetfo uhlolwa kangaki. Sihleli siyasebenta njalo emizuzwini lemi-5, ngako nome yini lengaphansi kwaloko isebenta njalo.",
