  "I am at the scene": "Ngisendzaweni",
  "I am not drawing a firearm this shift (e.g. mine is not on the armoury register). This is recorded on my start-of-shift record.": "Angitsatsi sibhamu kulelishifu (sib. sami asikho kulirejista lendzawo yetibhamu). Loku kubhalwa kurekhodi yami yekucala lishifu.",
  "I am not wearing a bodycam this shift. My reason is on my start-of-shift record and my supervisor sees it.": "Angigcokile i-bodycam kulelishifu. Sizatfu sami sikurekhodi yami yekucala lishifu futsi umphatsi wami uyasibona.",
  "I checked this ambulance and its stock myself, and the answers above are accurate.": "Ngiyihlolile le-ambulensi netimphahla tayo ngami ngekwami, futsi timphendvulo letingenhla tilungile.",
  "I confirm that I have physically inspected the above vehicle and that the information recorded is accurate to the best of my knowledge. Any faults noted must be reported to the immediate supervisor and recorded in the official pocket book.": "Ngiyacinisekisa kutsi ngiyihlolile imoto lengenhla ngemehlo futsi kutsi lwati lolubhaliwe lulungile ngekwalokwati kwami. Nobe ngumaphi emaphutsa labonakele kufanele abikwe kumphatsi masinyane futsi abhalwe encwadzini yesikhwama lesemtsetfweni.",
  "I explained the court date, and that paying the admission of guilt is a conviction and may give a criminal record.": "Ngichazile lilanga lenkantolo, nekutsi kukhokha kuvuma licala kulahlwa ngelicala futsi kungaletsa irekhodi yebugebengu.",
  "I explained the notice and the options: pay within 32 days for the discount, apply to pay in instalments (AARTO 04), or make a representation (AARTO 08).": "Ngichazile saziso netinketfo: khokha ngemalanga langu-32 kute utfole sephulelo, cela kukhokha ngetitavane (AARTO 04), nome wente sicelo (AARTO 08).",
  "I have an activation code": "Nginekhodi yekuvula",
  "I have read the POPIA notice (version {POPIA_NOTICE_VERSION})": "Ngifundzile saziso se-POPIA (luhlobo {POPIA_NOTICE_VERSION})",
  "I have read this shift": "Ngifundzile lelishifu",
  "I know how your department works and I can read the live board your role can see. Ask me anything, or tell me what to do. I prepare it, and nothing changes until you confirm.": "Ngiyati kutsi litiko lakho lisebenta njani futsi ngingafundza libhodi lelibukhoma lelibonwa sikhundla sakho. Ngibute nobe yini, nome ungitjele kutsi ngentani. Ngiyakulungisa, futsi kute lokushintjako uze uciniseke.",
  "I know your shift, your calls, your leave and your kit. Ask me anything about your work, in your own words. I explain and show you where to go; you do the work.": "Ngiyalati lishifu lakho, tincingo takho, likhefu lakho netimphahla takho temsebenti. Ngibute nobe yini ngemsebenti wakho, ngemavi akho. Ngiyachaza futsi ngikukhombise lapho kufanele uye khona; wena wenta umsebenti.",
  "I personally completed these checks and confirm that the answers and any defects recorded are accurate.": "Ngikwentile kuhlola loku ngami ngekwami futsi ngiyacinisekisa kutsi timphendvulo nemaphutsa lalabhaliwe kulungile.",
  "I will use HikTech only for official duties and keep my password private": "Ngitawusebentisa i-HikTech emisebentini lesemtsetfweni kuphela futsi ngigcine iphasiwedi yami iyimfihlo",
  "I'm on scene — it has not changed": "Ngisendzaweni — akushintjanga",
