  "Incidents routed to your department reach this phone even when the screen is locked. High and Critical incidents open a full-screen alert you must acknowledge.": "Tehlakalo letitfunyelwa elitikweni lakho tifika kulolucingo noma sikrini sivaliwe. Tehlakalo Letiphakeme naLetibucayi tivula sexwayiso lesigcwala sikrini lokufanele usamukele.",
