  "It is alleged that…": "Kusolwa kutsi…",
  "It is held on this phone and sends automatically, ahead of everything else, the moment you have signal. Do not wait — SMS or call the control room now.": "Igcinwe kulolucingo futsi itfunyelwa ngekwayo, ngaphambi kwako konkhe, ngaso leso sikhatsi utfola siginali. Ungalindzi — tfumela i-SMS nome ushayele i-control room nyalo.",
