  "Official After-Action Reports. Filing one resolves the incident.": "Imibiko Lesemtsetfweni Yangemuva Kwesento. Kufaka linye kucatulula sehlakalo.",
  "Official insignia belong to the municipality and its services, so the platform ships none — upload each department's real crest here and it appears everywhere immediately. Until then a monogram badge renders in that department's colours, so nothing ever looks unfinished. PNG or SVG with a transparent background works best; square crops read cleanest at small sizes.": "Timphawu letisemtsetfweni tetamasipala netinsita tawo, ngako-ke luhlelo alutifaki — layisha luphawu lwangempela lwelitiko ngalinye lapha futsi luvela yonkhe indzawo masinyane. Kuze kube ngulapho libheji letinhlamvu tekucala liboniswa ngemibala yalelo litiko, ngako-ke kute lokubukeka kungacedvwanga. I-PNG nome i-SVG lenendzawo lesemuva lecwebile isebenta kahle; titfombe letisikwele tifundzeka kahle nangabe tincane.",
