  "Only officers who went on duty in the app after today's start of shift are listed. Distance is straight-line from their last GPS heartbeat; ETA assumes {speedKmh} km/h with a {roadFactor}× road factor (Admin → Operations Settings).": "Kubalwa kuphela tikhulu letingene emsebentini ku-app ngemuva kwekucala kwelishifu lalamuhla. Libanga liyacondza kusuka kusiginali yabo yekugcina ye-GPS; i-ETA itsatsa {speedKmh} km/h nesici semgwaco lesingu-{roadFactor}× (Admin → Tilungiselelo Tekusebenta).",
  "Only one patient": "Sigulane sinye kuphela",
