  "Road traffic offences carry the AARTO Schedule 3 charge code and penalty; by-law offences carry the by-law section and the admission of guilt amount. Enter both from the official schedules, then verify. Changing a verified code or amount takes the verification off until someone checks it again.": "Emacala emgwaco aphetse ikhodi yelicala ye-AARTO Schedule 3 nenhlawulo; emacala emtsetfo wamasipala aphetse sigaba semtsetfo nemali yekuvuma licala. Faka kokubili kusuka etinhlelweni letisemtsetfweni, bese uyacinisekisa. Kushintja ikhodi nome imali lecinisekisiwe kususa kucinisekiswa kuze kube ngulapho umuntfu akuhlola futsi.",
  "Road traffic offences on AARTO 01 notices; by-law offences on Section 56 (offender present) or Section 341 (unattended vehicle) notices. Every charge has its own FN- number, and a served notice can never be edited or deleted — only cancelled, with a reason.": "Emacala emgwaco etatisweni te-AARTO 01; emacala emtsetfo wamasipala etatisweni teSigaba 56 (lowephule umtsetfo ukhona) nome teSigaba 341 (imoto lengagadvwanga). Licala ngalinye linenombolo yalo ye-FN-, futsi saziso lesinikiwe angeke sihlelwe nome sisulwe — singakhanselwa kuphela, ngesizatfu.",
