  "Upholstery": "Timbonyo tetihlalo",
  "Upload": "Layisha",
  "Upload evidence": "Layisha bufakazi",
  "Upload the day’s receipts from the cashier or the bank. Each row is matched to a fine by its FN- number or its notice number, and recorded with the date on the receipt — so a payment made inside the 32 days keeps the AARTO discount even when it is captured later. A receipt already on a fine is skipped, so importing the same file twice records nothing twice.": "Layisha emarisidi elilanga lavela kumkhasimende nome ebhange. Umugca ngamunye uhlanganiswa nenhlawulo ngenombolo yayo ye-FN- nome ngenombolo yesaziso sayo, futsi ubhalwe nelilanga leliselirisidini — ngako inkhokhelo leyentiwe ngekhatsi kwetinsuku letingu-32 igcina sephulelo se-AARTO noma ifakwe ngemuva. Lirisidi leselisenhlawulweni liyeciwa, ngako kungenisa lifayela lelifanako kabili akubhali lutfo kabili.",
