  "You are on duty, but today’s start of shift could not be confirmed. Check your signal and try again.": "Usemsebentini, kodvwa kucala kwelishifu lalamuhla akukhonanga kucinisekiswa. Hlola isiginali yakho bese uzama futsi.",
