  "You have not been placed on duty. Your answers were saved for supervisor review. Speak to your supervisor, then retake the check when your situation changes.": "Awukabekwa emsebentini. Timphendvulo takho tigcinelwe kubuyeketwa ngumphatsi. Khuluma nemphatsi wakho, bese uphindza kuhlola nangabe simo sakho sishintja.",
