  "Your PIN is locked after 5 wrong tries. Sign in with your password and choose a new PIN, or ask your supervisor to unlock it.": "I-PIN yakho ikhiyiwe ngemuva kwekuzama lokungakalungi kwa-5. Ngena ngephasiwedi yakho bese ukhetsa i-PIN lensha, nome ucele umphatsi wakho kutsi ayivule.",
